// Rich, POS-aware detail card for a saved Library word — the SAME breakdown the
// quick dictionary shows, fed by the entry's saved response_json (declension/
// conjugation, synonyms/antonyms/related, etymology, «как запомнить», examples +
// audio, level/frequency/IPA…). Mounts only when a word is expanded, so its own
// TTS hook is created on demand. Meanings are hidden here (the Library already
// renders «Значения» above). Tapping a synonym/collocation chip saves it.
// Server-internal / infra error text that must NEVER be shown to a user (DB / PgBouncer
// failures, stack traces, 5xx / gateway errors). We log the raw detail for ourselves and show
// a clean, human fallback instead — a user should see "что-то не загрузилось", not our plumbing.
const TECHNICAL_ERROR_RE = /internal server error|connection to server|pgbouncer|railway\.internal|password authentication|psycopg|operationalerror|sqlstate|traceback|could not connect|econnrefused|connection refused|bad gateway|gateway time|service unavailable|server closed the connection|remaining connection slots|too many connections/i;
function looksLikeTechnicalError(text) {
  return TECHNICAL_ERROR_RE.test(String(text || ''));
}

// Generic embedded deep card for a breakdown `item` (a lookup result or a saved
// response_json). Used by the Library detail and the Search result so both look
// exactly like the quick dictionary. Mounts its own TTS on demand; tapping a
// synonym/collocation chip saves it.
function EmbeddedWordCard({ item, hideMeanings }) {
  const tts = useDictTts();
  const [savedChips, setSavedChips] = useState(() => new Set());
  // Tap a synonym / related word / collocation → save it through the SAME canonical
  // pipeline as the quick dictionary (DictionaryOverlay.saveChip): a deterministic
  // quick-translate (RU gloss) IN PARALLEL with the GPT breakdown, so the chip is
  // stored as a proper card (article + translation + grammar + meta), NEVER bare
  // German. Omitting `quick`/`rich` was why chips saved German-only cards.
  const saveChip = useCallback((text) => {
    const t = String(text || '').trim();
    if (!t) return;
    setSavedChips((prev) => { if (prev.has(t)) return prev; const n = new Set(prev); n.add(t); return n; });
    dictHaptic('ok');
    (async () => {
      try {
        const pair = dictGuessPair(t);
        const [quickData, richData] = await Promise.all([
          dictApi('/api/translate/quick', { text: t, source_lang: pair.source, target_lang: pair.target }).catch(() => null),
          dictApi('/api/webapp/dictionary', { word: t, lookup_lang: pair.source }).catch(() => null),
        ]);
        const rich = richData?.item || null;
        if (rich) {
          rich.__direction = String(richData?.direction || rich.__direction || `${pair.source}-${pair.target}`).trim();
          rich.__language_pair = richData?.language_pair || null;
        }
        const detected = String(quickData?.detected_source_lang || pair.source).toLowerCase();
        const chipTargetLang = detected === pair.target ? pair.source : pair.target;
        const quick = quickData ? {
          source: t,
          translation: String(quickData?.translation || '').trim(),
          sourceLang: detected,
          targetLang: chipTargetLang,
          direction: `${detected}-${chipTargetLang}`,
        } : null;
        if (!rich && !(quick && quick.translation)) throw new Error('translate failed');
        await dictApi('/api/webapp/dictionary/save', buildDictionarySavePayload({
          rich, sourceText: t, quick, origin: 'webapp_related',
        }));
      } catch (_e) {
        setSavedChips((prev) => { const n = new Set(prev); n.delete(t); return n; });
      }
    })();
  }, []);
  // Tap an example SENTENCE → same canonical pipeline, but as a full sentence: use the
  // already-shown Russian gloss (fall back to a deterministic quick-translate), then
  // buildDictionarySavePayload so it's never saved German-only.
  const saveExample = useCallback((de, ru) => {
    const src = String(de || '').trim();
    if (!src) return;
    setSavedChips((prev) => { if (prev.has(src)) return prev; const n = new Set(prev); n.add(src); return n; });
    dictHaptic('ok');
    (async () => {
      try {
        let translation = String(ru || '').trim();
        if (!translation) {
          const q = await dictApi('/api/translate/quick', { text: src, source_lang: 'de', target_lang: 'ru' }).catch(() => null);
          translation = String(q?.translation || '').trim();
        }
        if (!translation) throw new Error('translate failed');
        await dictApi('/api/webapp/dictionary/save', buildDictionarySavePayload({
          rich: null,
          sourceText: src,
          quick: { source: src, translation, sourceLang: 'de', targetLang: 'ru', direction: 'de-ru' },
          origin: 'webapp_example',
        }));
      } catch (_e) {
        setSavedChips((prev) => { const n = new Set(prev); n.delete(src); return n; });
      }
    })();
  }, []);
  // Don't render an empty card for a bare quick-translate (no breakdown yet).
  const hasContent = item && typeof item === 'object' && (
    item.part_of_speech || item.meanings || item.grammar_tables || item.forms
    || item.etymology_note || item.memory_tip
    || (item.synonyms || []).length || (item.antonyms || []).length
    || (item.related_words || []).length || (item.common_collocations || []).length
    || (item.usage_examples || []).length || (item.government_patterns || []).length
  );
  if (!hasContent) return null;
  return (
    <div className="dq-card vocab-rich-card">
      <WordBreakdown item={item} tts={tts} hideMeanings={hideMeanings} onSaveChip={saveChip} onSaveExample={saveExample} savedChips={savedChips} />
    </div>
  );
}

function LibraryWordDetail({ item }) {
  const data = (item && typeof item.response_json === 'object' && item.response_json) ? item.response_json : null;
  if (!data) return null;
  return <EmbeddedWordCard item={data} hideMeanings />;
}

