// Transient "spotlight" for a paid-feature / limit notice. When the plate first
// appears it is centered above a blurred backdrop (portaled to <body> so no
// ancestor stacking context can hide it) and the inline copy is scrolled into
// view. It auto-dismisses (tap / Esc / timeout) and then the inline plate stays
// in place — these notices are persistent conditions, so the spotlight must
// never hard-block the section. Purely a visual focus aid; no behaviour change.
function PaidFeatureSpotlight({ children }) {
  const [open, setOpen] = useState(true);
  const inlineRef = useRef(null);
  useEffect(() => {
    const scrollTimer = window.setTimeout(() => {
      try {
        inlineRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      } catch (_e) { /* noop */ }
    }, 60);
    const closeTimer = window.setTimeout(() => setOpen(false), 5200);
    return () => {
      window.clearTimeout(scrollTimer);
      window.clearTimeout(closeTimer);
    };
  }, []);
  const overlay = open && typeof document !== 'undefined'
    ? createPortal(
      <div
        className="paid-feature-spotlight-overlay"
        role="button"
        tabIndex={0}
        aria-label="Закрыть"
        onClick={() => setOpen(false)}
        onKeyDown={(e) => {
          if (e.key === 'Escape' || e.key === 'Enter' || e.key === ' ') setOpen(false);
        }}
      >
        <div className="paid-feature-spotlight-stage" onClick={(e) => e.stopPropagation()}>
          {children}
        </div>
      </div>,
      document.body,
    )
    : null;
  return (
    <>
      <div ref={inlineRef} className="paid-feature-spotlight-inline">{children}</div>
      {overlay}
    </>
  );
}

// World-news quiz answer proof: the backend returns one raw string like
//   В тексте сказано: '...steht die AfD auf dem ersten Platz mit 27%...'
// Split it into a short label + a clean quote so we can render a real card
// instead of dumping the raw string with stray ASCII quotes and ellipses.
function cleanQuizProofQuote(raw) {
  let q = String(raw || '').trim();
  // Drop leading/trailing dots, ellipses and whitespace ("...text..." → "text").
  q = q.replace(/^[\s.…"'„«»”]+/, '').replace(/[\s.…"'„«»”]+$/, '');
  // German-style spacing before % (27% → 27 %, non-breaking).
  q = q.replace(/(\d)\s*%/g, '$1 %');
  return q.trim();
}

function parseWorldNewsQuizProof(raw) {
  const text = String(raw || '').trim();
  if (!text) return null;
  // Pull out the final quoted span (', ", „…", «…»).
  const match = text.match(/["'„«]([\s\S]+?)["'”»]\s*$/);
  if (!match) {
    return { label: '', quote: cleanQuizProofQuote(text) };
  }
  const label = text.slice(0, match.index).replace(/[\s:：—–-]+$/, '').trim();
  const quote = cleanQuizProofQuote(match[1]);
  if (!quote) return { label: '', quote: cleanQuizProofQuote(text) };
  return { label, quote };
}

function normalizeReaderPaginationText(rawText) {
  return String(rawText || '')
    .split(/\n{2,}/)
    .map((paragraph) => paragraph.replace(/\s*\n\s*/g, ' ').replace(/ {2,}/g, ' ').trim())
    .filter(Boolean)
    .join('\n\n');
}

function normalizeReaderVisiblePageText(rawText) {
  return String(rawText || '')
    // Strip "tofu" glyphs: Private-Use-Area, replacement/object-replacement, and
    // non-printable control chars (keep \n, \t). Universally safe for any book.
    .replace(/[\uE000-\uF8FF\uFFFC\uFFFD]+/g, ' ')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]+/g, ' ')
    // TABLE-OF-CONTENTS dot leaders ("Wiener Zeit....... 71"): a run of 4+ dots then
    // a page number becomes its own line "title \u00B7 71" (universal TOC convention,
    // language-independent; a 3-dot prose ellipsis is never caught).
    .replace(/(?:\s*[.\u00B7\u2022\u2219]\s*){4,}\s*([0-9]{1,4}|[IVXLCM]{1,7})\b/g, ' \u00B7 $1\n\n')
    .replace(/(?:\s*[.\u00B7\u2022\u2219]\s*){4,}/g, ' \u00B7 ')
    .replace(/\u2026{2,}/g, ' ')
    .split(/\n\n+/)
    .map((para) => para.replace(/\n/g, ' ').replace(/ {2,}/g, ' ').trim())
    .filter(Boolean)
    .join('\n\n');
}

function normalizeReaderEpubHref(rawHref) {
  return String(rawHref || '')
    .trim()
    .replace(/^https?:\/\/[^/]+/i, '')
    .replace(/^[./]+/, '')
    .split('#', 1)[0]
    .toLowerCase();
}

function readStoredReaderExactBookmarks() {
  if (typeof window === 'undefined') return {};
  try {
    const raw = String(window.localStorage.getItem(READER_LOCAL_BOOKMARKS_STORAGE_KEY) || '').trim();
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch {
    return {};
  }
}

function readStoredReaderExactBookmark(documentId) {
  const safeId = String(documentId || '').trim();
  if (!safeId) return null;
  const all = readStoredReaderExactBookmarks();
  const item = all[safeId];
  if (!item || typeof item !== 'object') return null;
  const page = Number(item.page || 0);
  if (!Number.isFinite(page) || page <= 0) return null;
  return {
    page,
    pageCount: Number(item.pageCount || 0),
    layoutMode: String(item.layoutMode || '').trim().toLowerCase() || '',
  };
}

function writeStoredReaderExactBookmark(documentId, payload) {
  if (typeof window === 'undefined') return;
  const safeId = String(documentId || '').trim();
  if (!safeId) return;
  try {
    const all = readStoredReaderExactBookmarks();
    all[safeId] = {
      page: Math.max(1, Number(payload?.page || 1)),
      pageCount: Math.max(0, Number(payload?.pageCount || 0)),
      layoutMode: String(payload?.layoutMode || '').trim().toLowerCase() || '',
      updatedAt: new Date().toISOString(),
    };
    window.localStorage.setItem(READER_LOCAL_BOOKMARKS_STORAGE_KEY, JSON.stringify(all));
  } catch {
    // ignore storage errors
  }
}

function readStoredReaderOriginalLocations() {
  if (typeof window === 'undefined') return {};
  try {
    const raw = String(window.localStorage.getItem(READER_LOCAL_ORIGINAL_LOCATIONS_STORAGE_KEY) || '').trim();
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch {
    return {};
  }
}

function readStoredReaderOriginalLocation(documentId) {
  const safeId = String(documentId || '').trim();
  if (!safeId) return null;
  const all = readStoredReaderOriginalLocations();
  const item = all[safeId];
  if (!item || typeof item !== 'object') return null;
  const cfi = String(item.cfi || '').trim();
  const progressPercent = Number(item.progressPercent || 0);
  return {
    cfi: cfi || '',
    progressPercent: Number.isFinite(progressPercent) ? Math.max(0, Math.min(100, progressPercent)) : 0,
  };
}

function writeStoredReaderOriginalLocation(documentId, payload) {
  if (typeof window === 'undefined') return;
  const safeId = String(documentId || '').trim();
  if (!safeId) return;
  try {
    const all = readStoredReaderOriginalLocations();
    all[safeId] = {
      cfi: String(payload?.cfi || '').trim(),
      progressPercent: Math.max(0, Math.min(100, Number(payload?.progressPercent || 0))),
      updatedAt: new Date().toISOString(),
    };
    window.localStorage.setItem(READER_LOCAL_ORIGINAL_LOCATIONS_STORAGE_KEY, JSON.stringify(all));
  } catch {
    // ignore storage errors
  }
}

function loadReaderEpubRuntime() {
  if (typeof window === 'undefined') {
    return Promise.reject(new Error('EPUB runtime is unavailable outside the browser'));
  }
  if (typeof window.ePub === 'function') {
    return Promise.resolve(window.ePub);
  }
  if (readerEpubRuntimePromise) {
    return readerEpubRuntimePromise;
  }
  readerEpubRuntimePromise = (async () => {
    for (const url of EPUB_RUNTIME_CDN_URLS) {
      try {
        await new Promise((resolve, reject) => {
          const existing = document.querySelector(`script[data-reader-epub-runtime="${url}"]`);
          if (existing) {
            existing.addEventListener('load', resolve, { once: true });
            existing.addEventListener('error', reject, { once: true });
            if (typeof window.ePub === 'function') {
              resolve();
            }
            return;
          }
          const script = document.createElement('script');
          script.async = true;
          script.src = url;
          script.dataset.readerEpubRuntime = url;
          script.onload = () => resolve();
          script.onerror = () => reject(new Error(`Failed to load ${url}`));
          document.body.appendChild(script);
        });
        if (typeof window.ePub === 'function') {
          return window.ePub;
        }
      } catch (_error) {
        // try the next CDN
      }
    }
    throw new Error('EPUB runtime failed to load');
  })();
  return readerEpubRuntimePromise;
}

function resolveStoredReaderExactBookmarkPage(storedBookmark, {
  pageCount = 0,
  layoutMode = '',
} = {}) {
  if (!storedBookmark || typeof storedBookmark !== 'object') return 0;
  const safePageCount = Math.max(0, Number(pageCount || 0));
  if (safePageCount <= 0) return 0;
  const storedPage = Math.max(0, Number(storedBookmark.page || 0));
  if (!Number.isFinite(storedPage) || storedPage <= 0) return 0;
  const storedPageCount = Math.max(0, Number(storedBookmark.pageCount || 0));
  const storedLayoutMode = String(storedBookmark.layoutMode || '').trim().toLowerCase();
  const safeLayoutMode = String(layoutMode || '').trim().toLowerCase();
  if (storedPageCount > 0 && storedPageCount !== safePageCount) return 0;
  if (safeLayoutMode && storedLayoutMode && safeLayoutMode !== storedLayoutMode) return 0;
  return Math.max(1, Math.min(safePageCount, storedPage));
}

function getReaderMeasureDimension(measureNode, axis = 'height') {
  if (!measureNode) return 0;
  const isWidth = axis === 'width';
  const ownSize = Number(isWidth ? measureNode.clientWidth : measureNode.clientHeight) || 0;
  const parent = measureNode.parentElement;
  const parentSize = Number(parent ? (isWidth ? parent.clientWidth : parent.clientHeight) : 0) || 0;
  return Math.max(ownSize, parentSize);
}

function readerPageTextFits(measureNode, text) {
  if (!measureNode) return false;
  measureNode.textContent = String(text || '');
  const availableHeight = Math.max(1, getReaderMeasureDimension(measureNode, 'height') - READER_PAGINATION_FIT_RESERVE_PX);
  return measureNode.scrollHeight <= availableHeight + 1;
}

const READER_HEADING_MINOR_WORDS = new Set([
  'a', 'an', 'and', 'as', 'at', 'by', 'for', 'from', 'in', 'into', 'of', 'on', 'or', 'the', 'to', 'und', 'oder',
  'der', 'die', 'das', 'dem', 'den', 'des', 'ein', 'eine', 'einer', 'einem', 'einen', 'im', 'am', 'vom', 'zum',
  'zur', 'von', 'mit', 'ohne', 'über', 'unter', 'vor', 'nach', 'bei', 'aus', 'als', 'ist', 'war', 'wie', 'zu',
  'и', 'в', 'во', 'на', 'с', 'со', 'к', 'ко', 'о', 'об', 'от', 'по', 'под', 'над', 'для', 'без', 'при', 'или',
  'а', 'но', 'что', 'как', 'из', 'у', 'за',
]);

function normalizeReaderHeadingWord(rawWord) {
  return String(rawWord || '')
    .replace(/^[^0-9A-Za-zА-Яа-яÄÖÜäöüẞßIVXLCDM]+|[^0-9A-Za-zА-Яа-яÄÖÜäöüẞßIVXLCDM]+$/g, '')
    .trim();
}

function isReaderTitleCaseWord(word) {
  const normalized = normalizeReaderHeadingWord(word);
  if (!normalized) return false;
  if (/^\d+(?:[.)]\d+)*(?:[.)])?$/.test(normalized)) return true;
  if (/^[IVXLCDM]+$/i.test(normalized) && normalized.length <= 8) return true;
  return /^[A-ZА-ЯÄÖÜẞ]/.test(normalized);
}

function isReaderHeadingParagraph(paragraph) {
  const text = String(paragraph || '').replace(/\s+/g, ' ').trim();
  if (!text) return false;
  if (text.length > 120) return false;
  const words = text.split(/\s+/).filter(Boolean);
  const wordCount = words.length;
  if (wordCount > 14) return false;
  if (/^(kapitel|chapter|teil|abschnitt|section|prolog|epilog)\b/i.test(text)) return true;
  if (/^(?:\d+(?:\.\d+)*|[IVXLCDM]+)[.)]?\s+[A-ZА-ЯÄÖÜẞ]/.test(text)) return true;
  if (/^[A-ZА-Я0-9ÄÖÜẞIVXLCDM .,:;'"“”«»()\-–—]+$/.test(text) && wordCount <= 12) return true;
  if (/[!?…]$/.test(text)) return false;
  if (/[.;]/.test(text) && !/:$/.test(text)) return false;

  const normalizedWords = words.map(normalizeReaderHeadingWord).filter(Boolean);
  const significantWords = normalizedWords.filter((word) => !READER_HEADING_MINOR_WORDS.has(word.toLowerCase()));
  const titleCaseWords = significantWords.filter(isReaderTitleCaseWord);
  const significantCount = significantWords.length;
  const titleCaseRatio = significantCount > 0 ? titleCaseWords.length / significantCount : 0;
  const hasSentenceLikePunctuation = /[,]/.test(text) || /[.!?…]$/.test(text);

  if (!hasSentenceLikePunctuation && wordCount <= 4 && titleCaseRatio >= 0.34) return true;
  if (!hasSentenceLikePunctuation && wordCount <= 8 && titleCaseRatio >= 0.6) return true;
  if (!hasSentenceLikePunctuation && wordCount <= 12 && titleCaseRatio >= 0.8) return true;
  if (/:$/.test(text) && wordCount <= 10) return true;
  return false;
}

function splitReaderTrailingHeadingBlock(text) {
  const paragraphs = String(text || '').split(/\n\n+/).map((item) => item.trim()).filter(Boolean);
  if (paragraphs.length < 2) return null;
  let splitIndex = paragraphs.length;
  while (splitIndex > 1 && isReaderHeadingParagraph(paragraphs[splitIndex - 1])) {
    splitIndex -= 1;
  }
  const headingCount = paragraphs.length - splitIndex;
  if (headingCount <= 0 || headingCount > 3) return null;
  const leading = paragraphs.slice(0, splitIndex).join('\n\n').trim();
  const trailing = paragraphs.slice(splitIndex).join('\n\n').trim();
  if (!leading || !trailing) return null;
  return { leading, trailing };
}

function findReaderBestFittingWordCount(measureNode, words, buildText) {
  if (!measureNode || !Array.isArray(words) || words.length === 0 || typeof buildText !== 'function') {
    return 0;
  }
  let low = 1;
  let high = words.length;
  let bestWordCount = 0;
  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    const midText = buildText(words.slice(0, mid));
    if (readerPageTextFits(measureNode, midText)) {
      bestWordCount = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  return bestWordCount;
}

function isReaderPaginationSane(sourceText, pages, measureNode) {
  const normalizedText = normalizeReaderPaginationText(sourceText);
  if (!normalizedText) return true;
  if (!Array.isArray(pages) || pages.length === 0) return false;

  const layoutWidth = getReaderMeasureDimension(measureNode, 'width');
  const layoutHeight = getReaderMeasureDimension(measureNode, 'height');
  if (layoutWidth <= 120 || layoutHeight <= 120) {
    return false;
  }

  const lengths = pages.map((item) => String(item || '').trim().length);
  const totalChars = lengths.reduce((sum, value) => sum + value, 0);
  const avgCharsPerPage = totalChars / Math.max(1, lengths.length);
  const tinyPages = lengths.filter((value) => value <= 3).length;

  if (normalizedText.length >= 80 && avgCharsPerPage < 12) {
    return false;
  }
  if (normalizedText.length >= 160 && avgCharsPerPage < 24) {
    return false;
  }
  if (pages.length > Math.ceil(normalizedText.length / 6)) {
    return false;
  }
  if (pages.length >= 12 && tinyPages >= Math.ceil(pages.length * 0.5)) {
    return false;
  }
  return true;
}

function paginateReaderText(text, measureNode) {
  const normalizedText = normalizeReaderPaginationText(text);
  if (!normalizedText || !measureNode) return [];
  if (getReaderMeasureDimension(measureNode, 'width') <= 0 || getReaderMeasureDimension(measureNode, 'height') <= 0) return [];

  const paragraphs = normalizedText.split(/\n\n+/).map((item) => item.trim()).filter(Boolean);
  const pages = [];
  let buffer = '';

  for (let paragraphIndex = 0; paragraphIndex < paragraphs.length; paragraphIndex += 1) {
    let paragraph = paragraphs[paragraphIndex];
    let stickyHeadingText = '';

    if (isReaderHeadingParagraph(paragraph)) {
      const headingParts = [paragraph];
      let nextIndex = paragraphIndex + 1;
      while (nextIndex < paragraphs.length && isReaderHeadingParagraph(paragraphs[nextIndex])) {
        headingParts.push(paragraphs[nextIndex]);
        nextIndex += 1;
      }
      if (nextIndex < paragraphs.length) {
        stickyHeadingText = headingParts.join('\n\n');
        paragraph = paragraphs[nextIndex];
        paragraphIndex = nextIndex;
      } else {
        paragraph = headingParts.join('\n\n');
        paragraphIndex = nextIndex - 1;
      }
    }

    let words = paragraph.split(/\s+/).filter(Boolean);
    while (words.length > 0) {
      const paragraphText = stickyHeadingText
        ? `${stickyHeadingText}\n\n${words.join(' ')}`
        : words.join(' ');
      const candidate = buffer ? `${buffer}\n\n${paragraphText}` : paragraphText;
      if (readerPageTextFits(measureNode, candidate)) {
        buffer = candidate;
        break;
      }

      if (buffer) {
        const bestWordCountWithBuffer = findReaderBestFittingWordCount(
          measureNode,
          words,
          (slice) => {
            const sliceText = stickyHeadingText
              ? `${stickyHeadingText}\n\n${slice.join(' ')}`
              : slice.join(' ');
            return `${buffer}\n\n${sliceText}`;
          }
        );
        if (bestWordCountWithBuffer > 0) {
          const sliceText = stickyHeadingText
            ? `${stickyHeadingText}\n\n${words.slice(0, bestWordCountWithBuffer).join(' ')}`
            : words.slice(0, bestWordCountWithBuffer).join(' ');
          pages.push(`${buffer}\n\n${sliceText}`);
          buffer = '';
          words = words.slice(bestWordCountWithBuffer);
          stickyHeadingText = '';
          continue;
        }
        const trailingHeadingBlock = splitReaderTrailingHeadingBlock(buffer);
        if (trailingHeadingBlock) {
          pages.push(trailingHeadingBlock.leading);
          buffer = trailingHeadingBlock.trailing;
          continue;
        }
        pages.push(buffer);
        buffer = '';
        continue;
      }

      if (stickyHeadingText) {
        const bestWordCount = findReaderBestFittingWordCount(
          measureNode,
          words,
          (slice) => `${stickyHeadingText}\n\n${slice.join(' ')}`
        );
        if (bestWordCount > 0) {
          pages.push(`${stickyHeadingText}\n\n${words.slice(0, bestWordCount).join(' ')}`);
          words = words.slice(bestWordCount);
          stickyHeadingText = '';
          continue;
        }
        if (readerPageTextFits(measureNode, stickyHeadingText)) {
          pages.push(stickyHeadingText);
          stickyHeadingText = '';
          continue;
        }
      }

      const bestWordCount = findReaderBestFittingWordCount(
        measureNode,
        words,
        (slice) => slice.join(' ')
      );
      if (bestWordCount > 0) {
        pages.push(words.slice(0, bestWordCount).join(' '));
        words = words.slice(bestWordCount);
        continue;
      }

      const firstWord = String(words[0] || '');
      if (!firstWord) {
        words.shift();
        continue;
      }

      let charLow = 1;
      let charHigh = firstWord.length;
      let bestCharCount = 1;
      while (charLow <= charHigh) {
        const mid = Math.floor((charLow + charHigh) / 2);
        const midText = firstWord.slice(0, mid);
        if (readerPageTextFits(measureNode, midText)) {
          bestCharCount = mid;
          charLow = mid + 1;
        } else {
          charHigh = mid - 1;
        }
      }

      pages.push(firstWord.slice(0, bestCharCount));
      words[0] = firstWord.slice(bestCharCount);
      if (!words[0]) {
        words.shift();
      }
    }
  }

  if (buffer) {
    pages.push(buffer);
  }

  measureNode.textContent = '';
  return pages;
}

function areReaderPagesEqual(prevPages, nextPages) {
  if (prevPages === nextPages) return true;
  if (!Array.isArray(prevPages) || !Array.isArray(nextPages)) return false;
  if (prevPages.length !== nextPages.length) return false;
  for (let index = 0; index < prevPages.length; index += 1) {
    const prevItem = prevPages[index];
    const nextItem = nextPages[index];
    if (Number(prevItem?.page_number || 0) !== Number(nextItem?.page_number || 0)) return false;
    if (String(prevItem?.text || '') !== String(nextItem?.text || '')) return false;
  }
  return true;
}

function getReaderPreferredLayoutMode() {
  // Every format now opens in the unified column engine (tap-translate + audio).
  // The separate original-EPUB (epub.js) renderer is no longer offered as a
  // user-facing choice, so we never default to 'original'.
  return 'custom';
}

function readStoredEconomicsPeriod() {
  if (typeof window === 'undefined') return 'month';
  try {
    const raw = String(window.localStorage.getItem(ECONOMICS_PERIOD_STORAGE_KEY) || '').trim().toLowerCase();
    return ECONOMICS_PERIOD_OPTIONS.has(raw) ? raw : 'month';
  } catch (_error) {
    return 'month';
  }
}

function readStoredEconomicsProvider() {
  if (typeof window === 'undefined') return 'all';
  try {
    const raw = String(window.localStorage.getItem(ECONOMICS_PROVIDER_STORAGE_KEY) || '').trim().toLowerCase();
    return raw || 'all';
  } catch (_error) {
    return 'all';
  }
}

function readStoredEconomicsForecastUsers() {
  if (typeof window === 'undefined') return '100';
  try {
    const raw = String(window.localStorage.getItem(ECONOMICS_FORECAST_USERS_STORAGE_KEY) || '').trim();
    return raw || '100';
  } catch (_error) {
    return '100';
  }
}

function readStoredDraftValue(key, fallback = '') {
  if (typeof window === 'undefined') return fallback;
  try {
    const raw = String(window.localStorage.getItem(key) || '').trim();
    return raw || fallback;
  } catch (_error) {
    return fallback;
  }
}

function writeStoredValue(key, value) {
  if (typeof window === 'undefined') return;
  try {
    window.localStorage.setItem(key, String(value || ''));
  } catch (_error) {
    // ignore storage failures
  }
}

function formatEconomicsProviderLabel(provider) {
  const value = String(provider || '').trim().toLowerCase();
  const labels = {
    all: 'All Providers',
    openai: 'OpenAI',
    google_tts: 'Google TTS',
    google_translate: 'Google Translate',
    deepl_free: 'DeepL',
    azure_translator: 'Azure Translator',
    livekit: 'LiveKit',
    cloudflare_r2_class_a: 'Cloudflare R2 Class A',
    cloudflare_r2_class_b: 'Cloudflare R2 Class B',
    cloudflare_r2_storage: 'Cloudflare R2 Storage',
    youtube_api: 'YouTube API',
    youtube_proxy: 'YouTube Proxy',
    perplexity: 'Perplexity',
    stripe: 'Stripe',
    agent_tts: 'Agent TTS',
    offline_tts: 'Offline TTS',
    app_internal: 'App Internal',
    libretranslate: 'LibreTranslate',
    mymemory: 'MyMemory',
    argos_offline: 'Argos Offline',
  };
  if (labels[value]) return labels[value];
  if (!value) return 'Unassigned';
  return value
    .split('_')
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');
}

function formatEconomicsUnitsLabel(unitsType, uiLang) {
  const value = String(unitsType || '').trim().toLowerCase();
  const map = {
    tokens_in: uiLang === 'de' ? 'Input-Tokens' : 'tokens in',
    tokens_out: uiLang === 'de' ? 'Output-Tokens' : 'tokens out',
    chars: uiLang === 'de' ? 'Zeichen' : 'chars',
    requests: uiLang === 'de' ? 'Anfragen' : 'requests',
    audio_minutes: uiLang === 'de' ? 'Audiominuten' : 'audio min',
    youtube_quota_units: uiLang === 'de' ? 'YouTube-Quota' : 'yt quota',
    operations: uiLang === 'de' ? 'Operationen' : 'ops',
    mb_month: uiLang === 'de' ? 'MB/Monat' : 'MB/month',
  };
  return map[value] || value || 'units';
}

function formatEconomicsCompactNumber(value) {
  const numeric = Number(value || 0);
  if (!Number.isFinite(numeric)) return '0';
  if (Math.abs(numeric) >= 100) return numeric.toFixed(0);
  if (Math.abs(numeric) >= 10) return numeric.toFixed(1);
  if (Math.abs(numeric) >= 1) return numeric.toFixed(2);
  return numeric.toFixed(3);
}

function formatBillingPriceLabel(plan, uiLang, fallbackLabel = '', forceOneTime = false) {
  const amountValue = Number(plan?.amount_value);
  const currency = String(plan?.currency || '').trim().toUpperCase();
  const interval = String(plan?.recurring_interval || '').trim().toLowerCase();
  const intervalCount = Number(plan?.recurring_interval_count || 1);
  if (!Number.isFinite(amountValue) || amountValue < 0 || !currency) {
    return String(fallbackLabel || '').trim();
  }
  const amountText = `${amountValue.toFixed(2)} ${currency}`;
  // Донат-тарифы — разовое «спасибо»: никогда не показываем «/мес», даже если в
  // Stripe цена пока заведена как recurring.
  if (forceOneTime) {
    const onceLabel = uiLang === 'de' ? 'einmalig' : 'разово';
    return `${amountText} · ${onceLabel}`;
  }
  if (!interval) {
    return amountText;
  }
  const intervalLabels = uiLang === 'de'
    ? { day: 'Tag', week: 'Woche', month: 'Monat', year: 'Jahr' }
    : { day: 'день', week: 'неделя', month: 'месяц', year: 'год' };
  const intervalLabel = intervalLabels[interval] || interval;
  if (intervalCount > 1) {
    return uiLang === 'de'
      ? `${amountText} / ${intervalCount} ${intervalLabel}`
      : `${amountText} / ${intervalCount} ${intervalLabel}`;
  }
  return `${amountText} / ${intervalLabel}`;
}

function formatDateInputValue(value) {
  const date = value instanceof Date ? new Date(value) : new Date(value || Date.now());
  if (Number.isNaN(date.getTime())) {
    return '';
  }
  const yyyy = String(date.getFullYear());
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const dd = String(date.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
}

function addCalendarDays(value, days) {
  const date = new Date(value || Date.now());
  if (Number.isNaN(date.getTime())) {
    return formatDateInputValue(new Date());
  }
  date.setDate(date.getDate() + Number(days || 0));
  return formatDateInputValue(date);
}

function buildDefaultAnalyticsCalendarRange() {
  const today = formatDateInputValue(new Date());
  return {
    startDate: addCalendarDays(today, -29),
    endDate: today,
  };
}

function beginAsyncGuard(ref) {
  const nextToken = Number(ref?.current || 0) + 1;
  ref.current = nextToken;
  return nextToken;
}

function invalidateAsyncGuard(ref) {
  return beginAsyncGuard(ref);
}

function invalidateAsyncGuards(...refs) {
  refs.forEach((ref) => {
    invalidateAsyncGuard(ref);
  });
}

function isAsyncGuardCurrent(ref, token) {
  return Number(ref?.current || 0) === Number(token || 0);
}

function parseIsoDateParts(value) {
  const raw = String(value || '').trim();
  const match = raw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) {
    return null;
  }
  return {
    year: Number(match[1]),
    month: Number(match[2]),
    day: Number(match[3]),
  };
}

function formatAnalyticsCalendarDisplayDate(value, locale = 'ru-RU') {
  const parts = parseIsoDateParts(value);
  if (!parts) {
    return '';
  }
  const safeDate = new Date(parts.year, parts.month - 1, parts.day);
  if (Number.isNaN(safeDate.getTime())) {
    return '';
  }
  return new Intl.DateTimeFormat(locale, {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  }).format(safeDate);
}

const HOME_SNAPSHOT_AUTO_REFRESH_MAX_AGE_MS = 60 * 60 * 1000;
const TODAY_PLAN_AUTO_REFRESH_MAX_AGE_MS = 60 * 60 * 1000;

function parseIsoTimestampMs(value) {
  const raw = String(value || '').trim();
  if (!raw) {
    return null;
  }
  const parsed = Date.parse(raw);
  return Number.isFinite(parsed) ? parsed : null;
}

function isSnapshotRefreshDue(value, maxAgeMs = HOME_SNAPSHOT_AUTO_REFRESH_MAX_AGE_MS) {
  const timestampMs = parseIsoTimestampMs(value);
  if (!Number.isFinite(timestampMs)) {
    return true;
  }
  return (Date.now() - timestampMs) >= maxAgeMs;
}

function formatSnapshotDateTime(value, locale = 'ru-RU') {
  const timestampMs = parseIsoTimestampMs(value);
  if (!Number.isFinite(timestampMs)) {
    return '';
  }
  return new Intl.DateTimeFormat(locale, {
    day: '2-digit',
    month: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  }).format(new Date(timestampMs));
}

function formatLimitResetDateTime(value, locale = 'ru-RU') {
  const timestampMs = parseIsoTimestampMs(value);
  if (!Number.isFinite(timestampMs)) {
    return '';
  }
  return new Intl.DateTimeFormat(locale, {
    day: '2-digit',
    month: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    timeZone: 'Europe/Vienna',
    timeZoneName: 'short',
  }).format(new Date(timestampMs));
}

