  const STORY_TOPIC = '🧩 ЗАГАДОЧНАЯ ИСТОРИЯ';
  const CUSTOM_TOPIC = '✍️ Свой грамматический фокус';
  const isStoryTopic = (value) => (value || '').includes('ЗАГАДОЧНАЯ ИСТОРИЯ');
  const isCustomTopic = (value) => String(value || '').trim() === CUSTOM_TOPIC;
  const normalizeSelectedTopicValue = useCallback((value) => {
    const rawValue = String(value || '').trim();
    if (isStoryTopic(rawValue)) {
      return STORY_TOPIC;
    }
    if (isCustomTopic(rawValue)) {
      return CUSTOM_TOPIC;
    }
    const exactMatch = topics.find((topic) => String(topic || '').trim() === rawValue);
    if (exactMatch) {
      return exactMatch;
    }
    return rawValue;
  }, [topics]);
  const resolveRecommendedTopicSelection = useCallback((topicLabel, fallbackCustomFocus = '') => {
    const rawTopicLabel = String(topicLabel || '').trim();
    const rawFallbackCustomFocus = String(fallbackCustomFocus || '').trim();
    if (!rawTopicLabel) {
      return null;
    }
    const normalizedTopic = normalizeSelectedTopicValue(rawTopicLabel);
    const hasExactTopicMatch = topics.some((topic) => String(topic || '').trim() === normalizedTopic);
    if (hasExactTopicMatch || normalizedTopic === CUSTOM_TOPIC || isStoryTopic(normalizedTopic)) {
      return {
        topic: normalizedTopic,
        customFocus: '',
      };
    }
    return {
      topic: CUSTOM_TOPIC,
      customFocus: rawFallbackCustomFocus || rawTopicLabel,
    };
  }, [normalizeSelectedTopicValue, topics]);
  const handleTopicChange = useCallback((event) => {
    setSelectedTopic(normalizeSelectedTopicValue(event?.target?.value));
  }, [normalizeSelectedTopicValue]);
  const inferTranslationRecommendationLevelFloor = useCallback((examples) => {
    const items = Array.isArray(examples) ? examples : [];
    const normalizeText = (value) => String(value || '').trim().replace(/\s+/g, ' ');
    const wordCount = (value) => {
      const matches = normalizeText(value).match(/[A-Za-zÀ-ÿА-Яа-яЁё0-9]+(?:[-'][A-Za-zÀ-ÿА-Яа-яЁё0-9]+)*/gu);
      return Array.isArray(matches) ? matches.length : 0;
    };
    const hasAnyMarker = (value, markers) => {
      const lowered = ` ${normalizeText(value).toLowerCase()} `;
      return markers.some((marker) => lowered.includes(marker));
    };
    const sentenceFitsLevel = (sentence, level) => {
      const text = normalizeText(sentence);
      if (!text) return false;
      const words = wordCount(text);
      const commaCount = (text.match(/,/g) || []).length;
      const hardPunctuation = (text.match(/[;:()]/g) || []).length;
      const dashCount = (text.match(/ — | - /g) || []).length;
      const mediumMarkers = [
        ' если ', ' когда ', ' потому что ', ' чтобы ', ' который', ' которая', ' которые',
        ' although ', ' because ', ' when ', ' if ', ' that ', ' which ',
        ' obwohl ', ' weil ', ' wenn ', ' dass ', ' damit ',
      ];
      const advancedMarkers = [
        ' несмотря на', ' в то время как', ' едва ', ' поскольку ', ' хотя ', ' так как ',
        ' whereby ', ' whereas ', ' provided that ', ' unless ', ' however ',
        ' während ', ' nachdem ', ' sofern ', ' indem ', ' weshalb ',
      ];
      const hasMedium = hasAnyMarker(text, mediumMarkers);
      const hasAdvanced = hasAnyMarker(text, advancedMarkers);
      if (level === 'a2') {
        return words >= 4 && words <= 12 && commaCount === 0 && hardPunctuation === 0 && dashCount === 0 && !hasMedium && !hasAdvanced;
      }
      if (level === 'b1') {
        return words >= 6 && words <= 18 && commaCount <= 2 && hardPunctuation <= 1 && !(hasAdvanced && words > 14);
      }
      if (level === 'b2') {
        return words >= 9 && words <= 24 && commaCount <= 3 && hardPunctuation <= 2 && (hasMedium || hasAdvanced || words >= 12);
      }
      if (level === 'c1') {
        return words >= 12 && words <= 30 && !(commaCount < 1 && !hasMedium && !hasAdvanced && words < 16);
      }
      if (level === 'c2') {
        return words >= 15 && words <= 36 && !(commaCount < 1 && !hasAdvanced && words < 20);
      }
      return false;
    };
    const rank = { a2: 1, b1: 2, b2: 3, c1: 4, c2: 5 };
    const observed = [];
    const seen = new Set();
    items.forEach((raw) => {
      const text = normalizeText(raw);
      if (!text) return;
      const key = text.toLowerCase();
      if (seen.has(key)) return;
      seen.add(key);
      for (const levelKey of ['c2', 'c1', 'b2', 'b1', 'a2']) {
        if (sentenceFitsLevel(text, levelKey)) {
          observed.push(levelKey);
          break;
        }
      }
    });
    if (!observed.length) return '';
    return observed.reduce((best, current) => (rank[current] > rank[best] ? current : best), observed[0]);
  }, []);
  const maxTranslationRecommendationLevel = useCallback((...levels) => {
    const rank = { a1: 1, a2: 2, b1: 3, b2: 4, c1: 5, c2: 6 };
    const normalized = levels
      .map((value) => String(value || '').trim().toLowerCase())
      .filter((value) => ['a1', 'a2', 'b1', 'b2', 'c1', 'c2'].includes(value));
    if (!normalized.length) return 'b1';
    return normalized.reduce((best, current) => (rank[current] > rank[best] ? current : best), normalized[0]);
  }, []);
  const buildTodayTranslationRecommendation = useCallback((item) => {
    if (!item || String(item?.task_type || '').toLowerCase() !== 'translation') {
      return null;
    }
    const payload = item?.payload && typeof item.payload === 'object' ? item.payload : {};
    const recommendedTopicLabel = String(payload?.recommended_topic_label || '').trim();
    const recommendedCustomFocus = String(
      payload?.recommended_custom_focus
      || payload?.sub_category
      || payload?.skill_title
      || payload?.main_category
      || ''
    ).trim();
    const reasonExamples = Array.isArray(payload?.recommended_reason_examples)
      ? payload.recommended_reason_examples
      : (Array.isArray(payload?.examples) ? payload.examples : []);
    const recommendedLevel = maxTranslationRecommendationLevel(
      payload?.recommended_level,
      payload?.level,
      inferTranslationRecommendationLevelFloor(reasonExamples),
    );
    const skillTitle = String(payload?.skill_title || '').trim();
    const subCategory = String(payload?.sub_category || '').trim();
    const mainCategory = String(payload?.main_category || '').trim();
    const localizedTopicLabel = getLocalizedSkillTopicLabel({
      skill_id: payload?.skill_id,
      skill_title: skillTitle,
      sub_category: subCategory,
      main_category: mainCategory,
    }, uiLang);
    const localizedRecommendedTopicLabel = recommendedTopicLabel
      ? getLocalizedSkillTopicLabel({
        skill_id: payload?.skill_id,
        skill_title: recommendedTopicLabel,
        sub_category: recommendedTopicLabel,
        main_category: mainCategory,
      }, uiLang)
      : '';
    return {
      itemId: Number(item?.id || 0),
      title: localizedTopicLabel || tr('Персональный фокус дня', 'Persönlicher Fokus des Tages'),
      reason: localizedTopicLabel,
      presetTopicLabel: recommendedTopicLabel,
      topicLabel: localizedRecommendedTopicLabel || localizedTopicLabel,
      customFocus: recommendedCustomFocus,
      level: recommendedLevel,
      examples: reasonExamples
        .map((entry) => String(entry || '').trim())
        .filter(Boolean)
        .slice(0, 2),
      createdAt: Date.now(),
    };
  }, [inferTranslationRecommendationLevelFloor, maxTranslationRecommendationLevel, tr, uiLang]);
  const applyTodayTranslationRecommendation = useCallback(() => {
    if (!todayTranslationRecommendation) return;
    const recommendedLevel = String(todayTranslationRecommendation?.level || '').trim().toLowerCase();
    if (['a1', 'a2', 'b1', 'b2', 'c1', 'c2'].includes(recommendedLevel)) {
      setSelectedLevel(recommendedLevel);
    }
    const recommendedPresetTopicLabel = String(todayTranslationRecommendation?.presetTopicLabel || '').trim();
    const recommendedCustomFocus = String(todayTranslationRecommendation?.customFocus || '').trim();
    if (recommendedPresetTopicLabel && recommendedPresetTopicLabel !== CUSTOM_TOPIC) {
      const resolvedSelection = resolveRecommendedTopicSelection(
        recommendedPresetTopicLabel,
        recommendedCustomFocus,
      );
      if (resolvedSelection) {
        setSelectedTopic(resolvedSelection.topic);
        setCustomTopicInput(resolvedSelection.customFocus);
        return;
      }
    }
    if (recommendedPresetTopicLabel === CUSTOM_TOPIC && recommendedCustomFocus) {
      setSelectedTopic(CUSTOM_TOPIC);
      setCustomTopicInput(recommendedCustomFocus);
      return;
    }
    if (recommendedCustomFocus) {
      setSelectedTopic(CUSTOM_TOPIC);
      setCustomTopicInput(recommendedCustomFocus);
    }
  }, [todayTranslationRecommendation, resolveRecommendedTopicSelection]);
