                    <div>
                      <div className="onboarding-eyebrow">{onboardingSlides[onboardingStep].eyebrow}</div>
                      <h3>{onboardingSlides[onboardingStep].title}</h3>
                    </div>
                    <button
                      type="button"
                      className="secondary-button onboarding-close"
