                  readerError={readerError}
                  readerErrorCode={readerErrorCode}

                  readerDocumentId={readerDocumentId}
                  readerTitle={readerTitle}
                  readerContent={readerContent}
                  readerPages={readerPages}
                  readerDisplayPages={readerDisplayPages}
