                  READER_DEFAULT_FONT_WEIGHT={READER_DEFAULT_FONT_WEIGHT}

                  readerColorTheme={readerColorTheme}
                  applyReaderColorTheme={applyReaderColorTheme}

                  audioElementRef={audioElementRef}
